"use strict";(self.webpackChunkgearflow_docs=self.webpackChunkgearflow_docs||[]).push([["796"],{1653(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/gearflow-docs/docs/intro","label":"GearFlow Docs","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/getting-started","label":"Getting Started","docId":"getting-started","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/getting-started/navigation","label":"Navigation","docId":"getting-started/navigation","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/getting-started/account-setup","label":"Account Setup","docId":"getting-started/account-setup","unlisted":false}],"collapsible":true},{"type":"category","label":"Inventory","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/inventory/overview","label":"Inventory","docId":"inventory/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/inventory/equipment","label":"Equipment","docId":"inventory/equipment","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/inventory/kits","label":"Kits","docId":"inventory/kits","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/inventory/accessories","label":"Accessories","docId":"inventory/accessories","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/inventory/categories","label":"Categories","docId":"inventory/categories","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/inventory/csv-import","label":"CSV Import / Export","docId":"inventory/csv-import","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/inventory/custom-fields","label":"Custom Fields","docId":"inventory/custom-fields","unlisted":false}],"collapsible":true},{"type":"category","label":"Projects","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/projects/overview","label":"Projects","docId":"projects/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/projects/creating-projects","label":"Creating Projects","docId":"projects/creating-projects","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/projects/line-items","label":"Line Items","docId":"projects/line-items","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/projects/quotes","label":"Quotes","docId":"projects/quotes","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/projects/templates","label":"Project Templates","docId":"projects/templates","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/projects/tasks","label":"Project Tasks","docId":"projects/tasks","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/projects/project-numbering","label":"Project Numbering","docId":"projects/project-numbering","unlisted":false}],"collapsible":true},{"type":"category","label":"Clients","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/clients/overview","label":"Clients","docId":"clients/overview","unlisted":false}],"collapsible":true},{"type":"category","label":"Documents","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/documents/overview","label":"Documents & PDFs","docId":"documents/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/documents/delivery-dockets","label":"Delivery Dockets","docId":"documents/delivery-dockets","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/documents/run-sheets","label":"Run Sheets","docId":"documents/run-sheets","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/documents/call-sheets","label":"Call Sheets","docId":"documents/call-sheets","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/documents/timeline","label":"Timeline PDF","docId":"documents/timeline","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/documents/template-designer","label":"Template Designer","docId":"documents/template-designer","unlisted":false}],"collapsible":true},{"type":"category","label":"Crew","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/crew/overview","label":"Crew","docId":"crew/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/crew/planner","label":"Crew Planner","docId":"crew/planner","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/crew/timesheets","label":"Timesheets","docId":"crew/timesheets","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/crew/certifications","label":"Certifications & Skills","docId":"crew/certifications","unlisted":false}],"collapsible":true},{"type":"category","label":"Suppliers","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/suppliers/overview","label":"Suppliers","docId":"suppliers/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/suppliers/purchase-orders","label":"Purchase Orders","docId":"suppliers/purchase-orders","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/suppliers/sub-hires","label":"Sub-Hires","docId":"suppliers/sub-hires","unlisted":false}],"collapsible":true},{"type":"category","label":"Warehouse","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/warehouse/overview","label":"Warehouse","docId":"warehouse/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/warehouse/check-in-check-out","label":"Check-In & Check-Out","docId":"warehouse/check-in-check-out","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/warehouse/pull-sheets","label":"Pull Sheets","docId":"warehouse/pull-sheets","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/warehouse/stocktake","label":"Stocktake","docId":"warehouse/stocktake","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/warehouse/reorder","label":"Reorder","docId":"warehouse/reorder","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/warehouse/damage","label":"Damage Capture","docId":"warehouse/damage","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/warehouse/displays","label":"Warehouse Displays","docId":"warehouse/displays","unlisted":false}],"collapsible":true},{"type":"category","label":"Compliance & Safety","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/compliance/overview","label":"Compliance & Safety","docId":"compliance/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/compliance/test-and-tag","label":"Test & Tag","docId":"compliance/test-and-tag","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/compliance/maintenance","label":"Maintenance","docId":"compliance/maintenance","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/compliance/workshop","label":"Workshop","docId":"compliance/workshop","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/compliance/check-items","label":"Check Items","docId":"compliance/check-items","unlisted":false}],"collapsible":true},{"type":"category","label":"Reports","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/reports/overview","label":"Reports","docId":"reports/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/reports/built-in-reports","label":"Built-in Reports","docId":"reports/built-in-reports","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/reports/custom-reports","label":"Custom Reports","docId":"reports/custom-reports","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/reports/utilization","label":"Asset Utilization","docId":"reports/utilization","unlisted":false}],"collapsible":true},{"type":"category","label":"Settings","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/settings/overview","label":"Settings","docId":"settings/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/settings/team-and-roles","label":"Team & Roles","docId":"settings/team-and-roles","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/settings/branding","label":"Branding","docId":"settings/branding","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/settings/integrations","label":"Integrations","docId":"settings/integrations","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/settings/billing","label":"Billing","docId":"settings/billing","unlisted":false}],"collapsible":true},{"type":"category","label":"Mobile","collapsed":false,"items":[{"type":"link","href":"/gearflow-docs/docs/mobile/overview","label":"Mobile & PWA","docId":"mobile/overview","unlisted":false},{"type":"link","href":"/gearflow-docs/docs/mobile/barcode-scanning","label":"Barcode Scanning","docId":"mobile/barcode-scanning","unlisted":false}],"collapsible":true}]},"docs":{"clients/overview":{"id":"clients/overview","title":"Clients","description":"The Clients module is your address book of everyone you rent equipment to \u2014 from one-off event organisers to repeat corporate accounts and production companies you work with season after season.","sidebar":"docsSidebar"},"compliance/check-items":{"id":"compliance/check-items","title":"Check Items","description":"Check items are the quality checks your crew runs on gear before it leaves the warehouse and again when it comes back. You define them once in a shared library, assign them to equipment models or kits, and from then on they appear automatically in the warehouse prep and return flows \u2014 so the inspection happens the same way every time, regardless of who\'s on shift.","sidebar":"docsSidebar"},"compliance/maintenance":{"id":"compliance/maintenance","title":"Maintenance","description":"The Maintenance module is your service log for every piece of gear you own \u2014 repairs, scheduled servicing, inspections, cleaning, and firmware updates. Each record links to one or more assets and tracks the work from the moment it\'s scheduled through to sign-off, holding the gear out of service so it can\'t accidentally get booked onto a project mid-repair.","sidebar":"docsSidebar"},"compliance/overview":{"id":"compliance/overview","title":"Compliance & Safety","description":"GearFlow\'s compliance tools help you meet regulatory obligations, track maintenance, manage repairs, and run quality checks on equipment before it goes out the door.","sidebar":"docsSidebar"},"compliance/test-and-tag":{"id":"compliance/test-and-tag","title":"Test & Tag","description":"Test & Tag is GearFlow\'s electrical safety testing module, built around AS/NZS 3760:2022. Most venues and event insurers won\'t let mains-powered gear on site without a current test tag, so this is the difference between loading in and being turned away at the dock. The module manages the full lifecycle \u2014 registering an item, running the test, recording the result, printing the label, and scheduling the next retest \u2014 so nothing ships with an expired tag.","sidebar":"docsSidebar"},"compliance/workshop":{"id":"compliance/workshop","title":"Workshop","description":"The Workshop page is a kanban board for your repair queue. Instead of digging through maintenance records one at a time, your service tech sees every job at a glance and drags it across the board as work progresses \u2014 from first assessment, through parts and bench work, to a final quality check. It\'s a live view over your maintenance records, not a separate system, so anything you log as a repair shows up here automatically.","sidebar":"docsSidebar"},"crew/certifications":{"id":"crew/certifications","title":"Certifications & Skills","description":"Certifications track the qualifications, tickets, and licences your crew hold \u2014 and, crucially, when they expire. Skills tag crew members with specific capabilities. Together they make sure the right person ends up on the right job, and that nobody gets rostered onto work they\'re no longer qualified to do.","sidebar":"docsSidebar"},"crew/overview":{"id":"crew/overview","title":"Crew","description":"The Crew module is your people database \u2014 every employee, freelancer, contractor, and volunteer you staff onto jobs, with their roles, skills, certifications, rates, availability, and project assignments in one place. When a festival weekend needs an FOH engineer, two riggers, and a system tech, this is where you find out who\'s qualified, who\'s free, and what they cost before you send the offer.","sidebar":"docsSidebar"},"crew/planner":{"id":"crew/planner","title":"Crew Planner","description":"The Crew Planner is a 14-day Gantt-style timeline of every active crew member\'s assignments and availability, all on one screen. It answers the question you ask a dozen times a week \u2014 \\"who\'s free?\\" \u2014 without phone calls or a whiteboard.","sidebar":"docsSidebar"},"crew/timesheets":{"id":"crew/timesheets","title":"Timesheets","description":"Timesheets track the hours your crew actually work \u2014 whether on a specific project or on general duties \u2014 so the gap between what you quoted for labour and what you owe at the end of the month is one you can see and control. Crew log their time, managers review and approve, and approved hours export straight to payroll.","sidebar":"docsSidebar"},"documents/call-sheets":{"id":"documents/call-sheets","title":"Call Sheets","description":"A call sheet tells every crew member where they need to be and when. It\'s the single source of truth your audio techs, riggers, and stagehands check before a job \u2014 call time, role, venue, who to find on arrival \u2014 so nobody\'s standing in a car park at 6am wondering which dock to use.","sidebar":"docsSidebar"},"documents/delivery-dockets":{"id":"documents/delivery-dockets","title":"Delivery Dockets","description":"A delivery docket is the document your crew takes to site. It\'s the paper trail that proves what left the warehouse, what arrived at the dock, and who signed for it \u2014 the thing you reach for when a client later says a wireless pack never turned up.","sidebar":"docsSidebar"},"documents/overview":{"id":"documents/overview","title":"Documents & PDFs","description":"GearFlow generates professional PDF documents directly from your projects \u2014 quotes, invoices, delivery dockets, return sheets, pull slips, call sheets, and timelines. Every document pulls live data straight from the project, so the gear list, crew schedule, dates, addresses, and pricing are always current and you never type the same thing twice.","sidebar":"docsSidebar"},"documents/run-sheets":{"id":"documents/run-sheets","title":"Run Sheets","description":"The run sheet is the day-of view your on-site crew lives in. It strips a project down to what matters on the ground \u2014 the venue, directions, the site contact, and every service for the day with the crew assigned to each \u2014 and presents it as a clean, mobile-first screen with no sidebars or tabs to wade through on a phone.","sidebar":"docsSidebar"},"documents/template-designer":{"id":"documents/template-designer","title":"Template Designer","description":"The template designer lets you control exactly how your documents look. Every document type \u2014 quotes, invoices, delivery dockets, return sheets, pull slips, and call sheets \u2014 can have its own customised template carrying your branding, your layout, and your wording.","sidebar":"docsSidebar"},"documents/timeline":{"id":"documents/timeline","title":"Timeline PDF","description":"The timeline PDF is the printable logistics schedule for a project \u2014 a date-grouped run of every service from first delivery to final pickup. Where the run sheet is the live screen your crew checks on site, the timeline is the branded document you file, print for the production office, or send to a client who wants the day-by-day plan in writing.","sidebar":"docsSidebar"},"getting-started":{"id":"getting-started","title":"Getting Started","description":"This guide walks you through creating your GearFlow account, setting up your organisation, and getting oriented with the dashboard.","sidebar":"docsSidebar"},"getting-started/account-setup":{"id":"getting-started/account-setup","title":"Account Setup","description":"Your account is the key to your entire rental operation \u2014 quotes worth tens of thousands, client contact details, asset values, and the warehouse history of every job you\'ve run. If a login leaks, someone could alter a quote going out to a venue, export your client list, or lock your crew out mid-bump-in. Securing your account isn\'t box-ticking; it\'s protecting the business.","sidebar":"docsSidebar"},"getting-started/navigation":{"id":"getting-started/navigation","title":"Navigation","description":"When a client calls mid-load-out asking whether their VL3500 Spots have left the building, you don\'t want to click through five menus to find out. GearFlow is built so you can jump to any asset, project, client, or warehouse view in a couple of keystrokes \u2014 the same speed you\'d expect from your phone\'s spotlight search. The faster you move through the app, the less time at a desk and the more time on the floor.","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"GearFlow Docs","description":"Welcome to GearFlow \u2014 the rental management platform built for AV, lighting, staging, and theatre production companies.","sidebar":"docsSidebar"},"inventory/accessories":{"id":"inventory/accessories","title":"Accessories","description":"An accessory is a child item that is inseparable from a parent asset \u2014 the hook clamp and safety bond that must travel with every moving light, the powerCON cable a fixture won\'t turn on without, the DMX terminator on a media server. You attach it to the parent once, and from then on GearFlow carries it everywhere the parent goes: onto quotes, onto pick sheets, out the door at deploy, and back onto the shelf at return.","sidebar":"docsSidebar"},"inventory/categories":{"id":"inventory/categories","title":"Categories","description":"Categories are the filing system for your catalogue. They organise your models and kits into a browsable, nested hierarchy so you \u2014 and everyone quoting, picking, or reporting \u2014 can find gear by type instead of scrolling a flat list of thousands of items. For example: Lighting > Moving Lights > Spot Fixtures.","sidebar":"docsSidebar"},"inventory/csv-import":{"id":"inventory/csv-import","title":"CSV Import / Export","description":"CSV import is how you get a whole catalogue into GearFlow at once instead of typing it in fixture by fixture. If you\'re switching from a spreadsheet, an old asset register, or another rental system, you export your data to CSV, map it to GearFlow\'s columns, and upload \u2014 hundreds of models and assets land in minutes. Export runs the other direction: pull your current inventory out for reporting, an insurance schedule, or a bulk rate update.","sidebar":"docsSidebar"},"inventory/custom-fields":{"id":"inventory/custom-fields","title":"Custom Fields","description":"Custom fields let you record the gear-specific details GearFlow doesn\'t capture out of the box. Every rental house tracks something idiosyncratic \u2014 a rig number painted on the road case, the firmware version on a media server, the DMX footprint of a moving light, or the date a wireless mic was last frequency-coordinated. Define those fields once and they appear on every asset form and detail page, so the data lives with the gear instead of in a technician\'s head or a sticky note.","sidebar":"docsSidebar"},"inventory/equipment":{"id":"inventory/equipment","title":"Equipment","description":"The Equipment page (sidebar: Inventory > Equipment) is the working catalogue of everything you own \u2014 serialised assets, bulk assets, and the models that describe them. This is where you build out your inventory once, so that quoting, pick sheets, and condition tracking all draw from the same accurate list. Spend the time here up front and the rest of the platform stops guessing.","sidebar":"docsSidebar"},"inventory/kits":{"id":"inventory/kits","title":"Kits","description":"A kit is a container that groups multiple assets so they rent as one unit. An \\"RF Rack Kit\\" might contain 4 wireless receivers, 4 beltpacks, and 4 lavalier mics in a rack case \u2014 one tag on the shelf, one line item on the project, one scan at deploy and return.","sidebar":"docsSidebar"},"inventory/overview":{"id":"inventory/overview","title":"Inventory","description":"The Inventory module is the single source of truth for every piece of gear your company owns \u2014 from a flagship lighting console down to a box of XLR cables. It tracks what you have, where it is, what condition it\'s in, and what it rents for, so the office can quote accurately and the warehouse can pick with confidence.","sidebar":"docsSidebar"},"mobile/barcode-scanning":{"id":"mobile/barcode-scanning","title":"Barcode Scanning","description":"GearFlow has a built-in barcode scanner that works with your device\'s camera \u2014 no external scanner gun needed. It reads standard barcodes and the QR codes GearFlow prints for your assets.","sidebar":"docsSidebar"},"mobile/overview":{"id":"mobile/overview","title":"Mobile & PWA","description":"GearFlow is a Progressive Web App (PWA) \u2014 it runs in your mobile browser but installs to your home screen and opens full-screen like a native app. There\'s no app store download, no separate version to keep updated, and it\'s the same GearFlow your office uses, just sized for a phone.","sidebar":"docsSidebar"},"projects/creating-projects":{"id":"projects/creating-projects","title":"Creating Projects","description":"A project is the container for one rental job \u2014 its client, dates, venue, equipment, pricing, and crew. Creating it is the first thing you do when an enquiry lands, and it takes under a minute: enough detail to start quoting, with everything else filled in as the job firms up.","sidebar":"docsSidebar"},"projects/line-items":{"id":"projects/line-items","title":"Line Items","description":"Line items are the individual pieces of equipment on a project \u2014 every console, amp, light, and cable you\'re sending out. They live inside the Equipment tab, where categories and groups turn a long flat list into something a client can read and a warehouse crew can pack.","sidebar":"docsSidebar"},"projects/overview":{"id":"projects/overview","title":"Projects","description":"A project in GearFlow represents a rental job \u2014 from the initial client enquiry all the way through to final invoicing. Every quote, equipment list, crew schedule, and document lives inside a project, so the whole job stays in one place instead of scattered across spreadsheets, emails, and a whiteboard in the warehouse.","sidebar":"docsSidebar"},"projects/project-numbering":{"id":"projects/project-numbering","title":"Project Numbering","description":"A project code is the short reference everyone uses for a job \u2014 on the quote, on the truck manifest, on the crew\'s call sheet, in the email subject line. GearFlow can generate these codes automatically from a pattern you define, so every new job gets a consistent, sequential reference without anyone having to remember what number comes next.","sidebar":"docsSidebar"},"projects/quotes":{"id":"projects/quotes","title":"Quotes","description":"A quote is the priced equipment list you send a client to win the job. In GearFlow it isn\'t a separate document you build by hand \u2014 it\'s generated straight from the project\'s groups and line items, with pricing, discount, and tax applied automatically. Get the equipment list and billing period right, and the quote takes care of itself.","sidebar":"docsSidebar"},"projects/tasks":{"id":"projects/tasks","title":"Project Tasks","description":"Every rental job has work around it that isn\'t equipment or crew \u2014 chasing a venue for loading dock access, confirming a power drop, booking the truck, sending the client their final running order. The Tasks tab keeps that work attached to the project itself, so it doesn\'t end up lost in Slack threads or a separate Asana board. It\'s a simple to-do list: create tasks, assign them to a person, and track them to done.","sidebar":"docsSidebar"},"projects/templates":{"id":"projects/templates","title":"Project Templates","description":"Project templates let you save a project\'s structure \u2014 categories, groups, line items, and services \u2014 to reuse for future jobs. The payoff is biggest on work you do over and over: instead of rebuilding the same equipment list from scratch every time, you start from a proven setup and just swap the dates and client.","sidebar":"docsSidebar"},"reports/built-in-reports":{"id":"reports/built-in-reports","title":"Built-in Reports","description":"Built-in reports are GearFlow\'s answers to the questions every rental manager asks on a Monday morning \u2014 what\'s overdue, who owes us money, which gear is sitting idle, where the maintenance budget went. There are roughly 30 of them, grouped by category in the report library, and each one runs against your live data with a single click. No setup, no query building.","sidebar":"docsSidebar"},"reports/custom-reports":{"id":"reports/custom-reports","title":"Custom Reports","description":"The custom report builder is for the questions the built-in reports don\'t cover. You pick a data source, choose the columns, filter and group the results, and preview it live before saving \u2014 no spreadsheets, no exporting raw data and pivoting it by hand. Once saved, a report can be shared with the team, pinned to the dashboard, and scheduled to email itself out on a recurring basis.","sidebar":"docsSidebar"},"reports/overview":{"id":"reports/overview","title":"Reports","description":"The Reports module gives you two ways to get insights from your data: a library of pre-built reports covering common questions, and a custom report builder for ad-hoc analysis.","sidebar":"docsSidebar"},"reports/utilization":{"id":"reports/utilization","title":"Asset Utilization","description":"The Utilization page answers a fundamental question: is this gear paying for itself? It shows per-asset booking rates, revenue, costs, and net contribution so you can identify your best-performing gear and find equipment that\'s costing you money.","sidebar":"docsSidebar"},"settings/billing":{"id":"settings/billing","title":"Billing","description":"The Billing section in Settings is where you manage your GearFlow subscription \u2014 your plan, the card you pay with, and every invoice.","sidebar":"docsSidebar"},"settings/branding":{"id":"settings/branding","title":"Branding","description":"The Branding section of Settings controls how GearFlow looks to your team inside the app \u2014 and, more importantly, how your business looks to the outside world on every document you send.","sidebar":"docsSidebar"},"settings/integrations":{"id":"settings/integrations","title":"Integrations","description":"Integrations connect GearFlow to the tools your business already runs on \u2014 your online store, your crew\'s chat app, and your company\'s identity provider. Instead of re-keying orders, chasing crew on WhatsApp, or managing a separate password for every team member, you let those systems talk to GearFlow directly. Configure them all from Settings > Integrations.","sidebar":"docsSidebar"},"settings/overview":{"id":"settings/overview","title":"Settings","description":"The Settings page is where you configure your organisation \u2014 from team members and branding to integrations and billing.","sidebar":"docsSidebar"},"settings/team-and-roles":{"id":"settings/team-and-roles","title":"Team & Roles","description":"The Team section of Settings lets you manage who has access to your GearFlow organisation and what they can do.","sidebar":"docsSidebar"},"suppliers/overview":{"id":"suppliers/overview","title":"Suppliers","description":"The Suppliers module keeps track of all the companies you buy or hire equipment from. Manage contact details, account info, and see related orders, assets, and sub-hires in one place.","sidebar":"docsSidebar"},"suppliers/purchase-orders":{"id":"suppliers/purchase-orders","title":"Purchase Orders","description":"A purchase order is your formal record of buying something from a supplier \u2014 gear you\'re adding to inventory, or consumables you\'re burning through on a job. Unlike a sub-hire, a PO is for things you keep: cables you\'ll re-rent for years, lamps you\'ll fit to a fixture, or a new moving light joining the fleet.","sidebar":"docsSidebar"},"suppliers/sub-hires":{"id":"suppliers/sub-hires","title":"Sub-Hires","description":"A sub-hire is gear you rent in from another supplier for a specific job because you don\'t own it, or don\'t own enough of it. You\'re the one on the hook to the client, but the kit comes from someone else\'s warehouse.","sidebar":"docsSidebar"},"warehouse/check-in-check-out":{"id":"warehouse/check-in-check-out","title":"Check-In & Check-Out","description":"Check-in and check-out is the heartbeat of a rental warehouse: getting gear out the door to a job and accounting for every piece when it comes back. GearFlow models this as a Prep \u2192 Deploy \u2192 Return flow, so a piece of equipment is never simply \\"out\\" or \\"in\\" \u2014 it\'s picked and packed, then physically dispatched, then checked back against its condition. This page covers each phase in detail.","sidebar":"docsSidebar"},"warehouse/damage":{"id":"warehouse/damage","title":"Damage Capture","description":"Gear comes back broken. A moving light takes a knock in transit, a cable returns with a crushed connector, a haze machine comes back from a corporate gig leaking fluid. Damage Capture lets you record exactly that \u2014 at the moment it lands on the return bench, with photos \u2014 instead of scribbling it on a clipboard and hoping someone follows up.","sidebar":"docsSidebar"},"warehouse/displays":{"id":"warehouse/displays","title":"Warehouse Displays","description":"A Warehouse Display is a live dashboard built for a wall-mounted TV or monitor on the warehouse floor \u2014 big text, dark background, readable from across the room, no login and no mouse. It answers the question every prep crew asks first thing in the morning: what\'s going out today, what\'s coming back, and is it all packed yet?","sidebar":"docsSidebar"},"warehouse/overview":{"id":"warehouse/overview","title":"Warehouse","description":"The Warehouse module is where you manage the physical flow of equipment \u2014 picking gear off the shelves, packing it into containers, deploying it to a project, and checking it back in when it returns.","sidebar":"docsSidebar"},"warehouse/pull-sheets":{"id":"warehouse/pull-sheets","title":"Pull Sheets","description":"A Pull Sheet is a printable list of every item in a project \u2014 the paper (or PDF) your warehouse team carries while they walk the shelves and pick gear. It\'s the bridge between what was quoted on a project and what physically leaves the building.","sidebar":"docsSidebar"},"warehouse/reorder":{"id":"warehouse/reorder","title":"Reorder","description":"Consumables are the gear you never think about until you run out. Gaffer tape, cable ties, lamps, batteries, gel, TrueCon and XLR leads \u2014 the bulk stock that quietly drains away across a busy month. The Reorder dashboard is your early-warning system: it watches every bulk item against the threshold you set and surfaces anything running low, grouped by the supplier you\'d actually buy it from.","sidebar":"docsSidebar"},"warehouse/stocktake":{"id":"warehouse/stocktake","title":"Stocktake","description":"A stocktake is a physical inventory count: you walk a location, scan everything that\'s actually on the shelf, and GearFlow tells you where reality and the system disagree. It\'s how you catch the slow drift that creeps into every rental warehouse \u2014 a fixture that never got checked back in, a box of cables that walked onto a job and never returned, stock sitting in the wrong room.","sidebar":"docsSidebar"}}}}')}}]);